-- Hyprland 0.57+ (Lua config) — sura
-- Everything lives in ./conf; edit those, Hyprland auto-reloads on save.
--
--   conf/env.lua        environment variables (Wayland, Qt/GTK, NVIDIA)
--   conf/monitors.lua   displays
--   conf/colors.lua     GENERATED by wallust from the current wallpaper — don't edit
--   conf/look.lua       gaps, borders, rounding, blur, shadows, animations
--   conf/input.lua      keyboard / mouse
--   conf/autostart.lua  programs started with the session
--   conf/rules.lua      window / layer rules
--   conf/keybinds.lua   all shortcuts (SUPER+H shows them)

require("conf.env")
require("conf.monitors")
require("conf.look")
require("conf.input")
require("conf.autostart")
require("conf.rules")
require("conf.keybinds")

-- Machine-local overrides that shouldn't go in the dotfiles repo (optional).
pcall(require, "conf.local")
